(function () {
  'use strict';

  const root = document.documentElement;

  /* Animation is on unless the visitor switched it off with #btn-motion.
     The OS "show animations" setting is deliberately not consulted. */
  const motionOn = () => root.dataset.motion !== 'reduced';

  /* ── Footer year ─────────────────────────────────────────────────────── */
  const yearEl = document.getElementById('year');
  if (yearEl) yearEl.textContent = new Date().getFullYear();

  /* ── Logo video ──────────────────────────────────────────────────────── */
  const video = document.getElementById('logo-video');
  function syncVideo() {
    if (!video) return;
    if (motionOn()) video.play().catch(() => {});
    else video.pause();
  }
  syncVideo();

  /* ── Toast ───────────────────────────────────────────────────────────── */
  const toast = document.getElementById('toast');
  let toastTimer;
  function showToast(msg, ms = 2200) {
    if (!toast) return;
    clearTimeout(toastTimer);
    toast.textContent = msg;
    toast.classList.add('show');
    toastTimer = setTimeout(() => toast.classList.remove('show'), ms);
  }

  /* ── Motion switch ───────────────────────────────────────────────────── */
  const motionBtn = document.getElementById('btn-motion');
  function paintMotionBtn() {
    if (!motionBtn) return;
    motionBtn.textContent = motionOn() ? 'motion: on' : 'motion: off';
  }
  if (motionBtn) {
    paintMotionBtn();
    motionBtn.addEventListener('click', () => {
      const turnOff = motionOn();
      root.dataset.motion = turnOff ? 'reduced' : 'full';
      try { localStorage.setItem('rocmine-motion', turnOff ? 'off' : 'on'); } catch (e) { /* storage blocked */ }
      paintMotionBtn();
      syncVideo();
      showToast(turnOff ? 'animations off' : 'animations on', 1400);
    });
  }

  /* ── Copy email (footer button + hero button); falls back to mailto ──── */
  document.querySelectorAll('[data-email]').forEach(el => {
    const email = el.dataset.email || 'amine.rochdi@rocmine.net';
    el.addEventListener('click', async e => {
      e.preventDefault();
      try {
        await navigator.clipboard.writeText(email);
        showToast('✓ copied to clipboard');
      } catch (err) {
        window.location.href = `mailto:${email}`;
        showToast('opening mail client…');
      }
    });
  });

  /* ── External link toasts ────────────────────────────────────────────── */
  ['btn-github', 'btn-linkedin'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('click', () =>
      showToast(`opening ${id === 'btn-github' ? 'github' : 'linkedin'}…`, 1400));
  });

  /* ── Typewriter on role text ─────────────────────────────────────────── */
  const roleEl = document.querySelector('.role-text');
  if (roleEl && motionOn()) {
    const full = roleEl.textContent;
    roleEl.textContent = '';
    let i = 0;
    // wait for the reveal animation (d-1 = 140ms + ~500ms)
    setTimeout(() => {
      const iv = setInterval(() => {
        roleEl.textContent += full[i++];
        if (i >= full.length) clearInterval(iv);
      }, 34);
    }, 480);
  }

  /* ── Diagrams: draw once when scrolled into view ─────────────────────── */
  const diagrams = document.querySelectorAll('.diagram');
  if (diagrams.length) {
    if (!('IntersectionObserver' in window)) {
      diagrams.forEach(d => d.classList.add('in'));
    } else {
      const io = new IntersectionObserver((entries) => {
        entries.forEach(e => {
          if (!e.isIntersecting) return;
          e.target.classList.add('in');
          io.unobserve(e.target);
        });
      }, { threshold: 0.2 });
      diagrams.forEach(d => io.observe(d));
    }
  }

})();
/* ─── ROCMINE Portfolio ─ title.js ───────────────────────────────────────────
   Pointer proximity for the big name: letters near the cursor lift and glow.
   Touch: a tap sends one wave through the letters. Does nothing when motion is off.
   The load animation and the glint wave are pure CSS (src/css/31-title.css). */

(function () {
  'use strict';

  const block = document.querySelector('.name-block');
  if (!block) return;

  const root = document.documentElement;
  const motionOn = () => root.dataset.motion !== 'reduced';
  const letters = [...block.querySelectorAll('.ch')];
  if (!letters.length) return;

  /* Release the line mask once the last letter has risen (see .intro-done in the CSS) */
  const last = letters[letters.length - 1];
  const release = () => block.classList.add('intro-done');
  if (motionOn()) last.addEventListener('animationend', e => { if (e.animationName === 'ch-rise') release(); }, { once: true });
  setTimeout(release, 3500);                      // safety net, also covers "motion off"

  /* ── pointer proximity (mouse / pen only) ─────────────────────────────── */
  const RADIUS = 150;                             // px of influence around the cursor
  let centers = [];
  let pointer = null, raf = 0;

  function measure() {
    const b = block.getBoundingClientRect();
    centers = letters.map(el => ({
      el,
      x: b.left + el.offsetLeft + el.offsetWidth / 2,
      y: b.top + el.offsetTop + el.offsetHeight / 2,
    }));
  }

  function frame() {
    raf = 0;
    if (!pointer || !motionOn()) return clear();
    measure();                                    // cheap (about 20 letters) and always correct after scroll/resize
    for (const c of centers) {
      const d = Math.hypot(c.x - pointer.x, c.y - pointer.y);
      const t = Math.max(0, 1 - d / RADIUS);
      c.el.style.setProperty('--near', (t * t * (3 - 2 * t)).toFixed(3));
    }
  }

  function clear() { letters.forEach(el => el.style.removeProperty('--near')); }
  function schedule() { if (!raf) raf = requestAnimationFrame(frame); }

  window.addEventListener('pointermove', e => {
    if (e.pointerType === 'touch') return;
    pointer = { x: e.clientX, y: e.clientY };
    schedule();
  }, { passive: true });
  document.addEventListener('pointerleave', () => { pointer = null; schedule(); });

  /* ── touch: tap the name for one wave ─────────────────────────────────── */
  block.addEventListener('pointerdown', e => {
    if (e.pointerType !== 'touch' || !motionOn() || !letters[0].animate) return;
    letters.forEach((el, i) => el.animate(
      [{ translate: '0 0' }, { translate: '0 -0.16em' }, { translate: '0 0' }],
      { duration: 520, delay: i * 26, easing: 'ease-out' }));
  });
})();
